241	      return { type: "prompt.submit", id: requestId, text };
242	    }
243	    case "steer": {
244	      const requestId = requireId("steer");
245	      const text = msg.text;
246	      if (typeof text !== "string" || !text.trim()) throw new ProtocolError("steer requires non-empty text", requestId);
247	      return { type: "steer", id: requestId, text };
248	    }
249	    case "cancel":
250	      return { type: "cancel" };
251	    case "approve":
252	      return { type: "approve", id: requireId("approve"), always: msg.always === true };
