/**
 * Pure convergence scheduling over durable operation state. OperationRunner owns time, execution and persistence.
 */
import type {
  AppliedDecision,
  Assignment,
  BlockSpec,
  Decision,
  DecisionAction,
  DecisionOption,
  DurableOperationState,
  EscalationDecision,
  OperationEvent,
  OperationEventType,
  OptionSpec,
  UnitRunResult,
  WorkUnit,
  WorkUnitStatus,
} from "./operation.js";
import { MAX_REJECTED_OUTPUT_CHARS, MAX_REJECTED_OUTPUTS, unitBaseTask } from "./operation.js";
import { specialistInputsProblem } from "./specialist_profiles.js";
import { redactForPersistence } from "./persistence_protection.js";
import type { ResourceDescriptor, ResourceRegistry, Selection } from "./resources.js";
import { reportOperationDiagnostic, type OperationDiagnosticHandler } from "./operation_runner_diagnostics.js";
import { effectiveConcurrency } from "./operation_schema.js";

/** Separates a unit's original task from operator revisions appended to it. */
export const REVISION_MARKER = "\n\nOperator revision: ";
const MAX_EVENTS = 300;
const TERMINAL: WorkUnitStatus[] = ["COMPLETE", "BLOCKED"];

function clockTime(ms: number): string {
  return new Date(ms).toISOString().slice(11, 16) + " UTC";
}

/** An operator decision Nexus will not apply (stale, not offered, or outside the unit's authority). */
export class DecisionRejected extends Error {}

export const isRequired = (u: Pick<WorkUnit, "required">): boolean => u.required !== false;

/**
 * Whether `dependency` is finished input for `u`: COMPLETE, or, for a failure_debugger in an isolated operation only,
 * BLOCKED on a run whose verifier did not pass. The failure is that role's input, so waiting for the dependency to
 * complete would wait for the evidence to disappear; a retried dependency is unfinished input again. Only an isolated
 * operation gives the debugger a snapshot of the failed candidate: elsewhere it would run in the shared workspace on
 * top of the blocked unit's uncommitted candidate, so it keeps waiting.
 */
function dependencySatisfied(u: WorkUnit, dependency: WorkUnit, isolated: boolean): boolean {
  if (dependency.status === "COMPLETE") return true;
  return isolated && u.role === "failure_debugger" && dependency.status === "BLOCKED" && dependency.failedRun !== undefined;
}

export class ConvergenceScheduler {
  constructor(
    readonly state: DurableOperationState,
    readonly registry: ResourceRegistry,
    private readonly now: () => number,
    private readonly onEvent?: (e: OperationEvent) => void,
    private readonly onDiagnostic?: OperationDiagnosticHandler,
  ) {}
